	('cmvp9ia6f000aac7d493maey7', 'cmvp9i9zj0000ac7dwbnpwssi', 'ADR-001', 'SUBMITTED', 'cmvp9ia3m0001ac7dej3f7h83', NULL, NULL, '2026-10-18 05:00:00', '2026-10-18 05:00:00', NULL, 1, 0, false, 'R.K.', 34, 'YEARS', NULL, false, 'FEMALE', 58, 'Maculopapular rash', 'Itchy red maculopapular rash over the trunk and both arms, first noticed two days after starting amoxicillin.', 'Amoxicillin stopped on 15/10/2026. Cetirizine 10 mg once daily started. Rash improving by 17/10/2026.', '2026-10-14', false, NULL, false, false, 'No previous drug allergy recorded.', '{}', 'NO', '{}', NULL, false, 'RECOVERING', NULL, '{}', 'Demo Clinical Pharmacist', 'Demo General Hospital (Fictional), Demo City', '000000', 'pharmacist@demo.test', '+91 00000 00001', 'Clinical Pharmacist', '2026-10-18', '2026-10-18 04:20:00', '2026-10-18 05:00:00', NULL),
	('cmvp9ia7f000gac7dmehc8wfl', 'cmvp9i9zj0000ac7dwbnpwssi', 'ADR-002', 'DRAFT', 'cmvp9ia3m0001ac7dej3f7h83', NULL, NULL, NULL, NULL, NULL, 0, 0, false, 'S.P.', 61, 'YEARS', NULL, false, 'MALE', NULL, 'Dry cough', NULL, NULL, '2026-09', false, NULL, false, false, NULL, '{}', NULL, '{}', NULL, false, NULL, NULL, '{}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-10-20 10:35:00', '2026-10-20 10:50:00', NULL),
	('cmvp9ia7u000jac7d045d2bjg', 'cmvp9i9zj0000ac7dwbnpwssi', 'ADR-003', 'UNDER_REVIEW', 'cmvp9ia3v0002ac7dlmwlcqbn', 'cmvp9ia450003ac7doqgdr645', '2026-10-21 03:45:00', '2026-10-20 10:10:00', '2026-10-20 10:10:00', NULL, 1, 0, false, 'A.M.', 52, 'YEARS', NULL, false, 'MALE', 81, 'Nausea; diarrhoea', 'Nausea and loose stools (three to four a day) starting four days after metformin was started.', 'Advised to take metformin with meals; oral fluids.', '2026-10-08', false, NULL, false, true, 'Type 2 diabetes mellitus, newly diagnosed.', '{}', 'NO', '{}', NULL, false, 'RECOVERING', NULL, '{}', 'Demo Resident Physician', 'Demo General Hospital (Fictional), Demo City', '000000', 'physician@demo.test', '+91 00000 00002', 'Physician', '2026-10-20', '2026-10-20 09:40:00', '2026-10-21 04:12:00', NULL),
	('cmvp9ia91000vac7drsf8ow98', 'cmvp9i9zj0000ac7dwbnpwssi', 'ADR-004', 'RETURNED', 'cmvp9ia3m0001ac7dej3f7h83', 'cmvp9ia4r0008ac7dnyqoyx38', '2026-10-17 03:30:00', '2026-10-16 05:30:00', '2026-10-16 05:30:00', NULL, 1, 0, false, 'N.D.', 45, 'YEARS', NULL, false, 'FEMALE', 64, 'Achilles tendon pain', 'Pain and tenderness over the left Achilles tendon after starting ciprofloxacin.', 'Ciprofloxacin discontinued. Rest advised; paracetamol as needed.', '2026-10-11', false, NULL, false, false, NULL, '{}', 'NO', '{}', NULL, false, 'RECOVERING', NULL, '{}', 'Demo Clinical Pharmacist', 'Demo General Hospital (Fictional), Demo City', '000000', 'pharmacist@demo.test', '+91 00000 00001', 'Clinical Pharmacist', '2026-10-16', '2026-10-16 04:50:00', '2026-10-17 04:35:00', NULL),
