	('cmvp9iacc001sac7d3b6f7ikn', 'cmvp9i9zj0000ac7dwbnpwssi', 'ADR-006', 'SUBMITTED', 'cmvp9ia3m0001ac7dej3f7h83', NULL, NULL, '2026-10-22 02:40:00', '2026-10-22 02:40:00', NULL, 1, 0, true, 'P.S.', 29, 'YEARS', NULL, false, 'FEMALE', 55, 'Generalised urticaria; hypotension', 'Widespread urticaria with a fall in blood pressure about 20 minutes into an intravenous ceftriaxone infusion.', 'Infusion stopped. Intravenous hydrocortisone and intravenous fluids given. Admitted for observation.', '2026-10-21', false, NULL, false, false, 'No previous drug allergy recorded.', '{}', 'YES', '{HOSPITALISATION}', NULL, false, 'RECOVERING', NULL, '{}', 'Demo Clinical Pharmacist', 'Demo General Hospital (Fictional), Demo City', '000000', 'pharmacist@demo.test', '+91 00000 00001', 'Clinical Pharmacist', '2026-10-22', '2026-10-22 02:00:00', '2026-10-22 02:40:00', NULL),
