-- ADR Reporter: fictional demonstration data (generated from prisma/seed.ts).
-- 1 fictional institution, 9 demo accounts (password for all: AdrDemo#2026) and
-- 8 fictional cases ADR-001 to ADR-008 in different states. No real patient data.
-- Stops without changing anything if data is already loaded.

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM public."Institution") THEN
    RAISE EXCEPTION 'Demo data is already loaded; nothing was changed.';
  END IF;
END $$;

